('603','europe','lenin-stalin-gorbachev-reference','Lenin work — The State and Revolution','উৎসে *The State and Revolution* Lenin-এর উল্লেখযোগ্য গ্রন্থ হিসেবে আছে।','high','a08d3a3cba6706c1fd84a8a52d39eb7704ddf242e18c66ea4aa1fe8b0426e0f5'),
('603','europe','lenin-stalin-gorbachev-reference','Lenin work — Imperialism, the Highest Stage of Capitalism','উৎসে *Imperialism, the Highest Stage of Capitalism* Lenin-এর উল্লেখযোগ্য গ্রন্থ হিসেবে আছে।','high','f1db915afc6f72d19811fdb63eb15fb90c558e56d647839098433aa459156985'),
('603','europe','lenin-stalin-gorbachev-reference','Lenin work — Left-Wing Communism','উৎসে *Left-Wing Communism* Lenin-এর উল্লেখযোগ্য গ্রন্থ হিসেবে মুদ্রিত আছে; পূর্ণ subtitle scan-এ নেই।','high','2d0e3122be8ee68c16396d8834c4f799260d6ea5abc3b7555653e16e7a3a6fc4'),
('603','europe','lenin-stalin-gorbachev-reference','Lenin work — The Development of Capitalism in Russia','উৎসে *The Development of Capitalism in Russia* Lenin-এর উল্লেখযোগ্য গ্রন্থ হিসেবে আছে।','high','76cc851ee406c9df7e6c35b155bfe23e416681ecf91538a34cc1614c43e3fa36'),
('603','europe','lenin-stalin-gorbachev-reference','Great Terror — Stalin-era historic context','Library of Congress অনুযায়ী 1930-এর দশকের Great Terror Stalin-এর absolute dominance নিশ্চিত করার police terror ছিল; এটি historic repression contextে রাখা হয়েছে।','high','ebe4f43076ce16060d9df486b4de2526ada320940277c3f6768dfc1fa847016f'),
('603','europe','lenin-stalin-gorbachev-reference','Mikhail Gorbachev — final Soviet President','National Security Archive Gorbachev-কে Soviet Union-এর first and last President হিসেবে বর্ণনা করে; এটি historic office contextে রাখা হয়েছে।','high','a92cf8bfa192d40fc70a1b1f45f3c5969a84f51f30d04947efa25109703c43ea'),
('603','europe','lenin-stalin-gorbachev-reference','Soviet collapse — 1991 Gorbachev tenure context','Library of Congress ও National Security Archive 1991 Soviet collapse-এর historic Gorbachev-era context দেয়; একক-কারণ assertion করা হয়নি।','high','357651347acc5e4f5a9f9348524a9cba128468e4717f61226f2c2c5a5d991786'),
('603','europe','lenin-stalin-gorbachev-reference','Glasnost and Perestroika — historic reform terms','উৎসে Gorbachev-এর সঙ্গে Glasnost ও Perestroika উল্লেখ আছে; National Security Archive reform contextে Perestroika বর্ণনা করে।','high','bbc6c551dc4cb8a507b4ab7b8e2a8be3fe4e16eee882a7c671a1bae94752adcc'),
('603','europe','lenin-stalin-gorbachev-reference','Perestroika — 1987 reform-programme source reference','উৎসে Gorbachev ১৯৮৭ সালে রাজনৈতিক ও অর্থনৈতিক reform programme চালু করেন বলা হয়েছে; এটি source-attributed historic reference।','medium','77c9f61f60e8fd26443e6a31648a97253d640d18d0c6f3383ac53e85013e34bd')) INSERT INTO public.gk_facts (book_id,chapter_id,topic_id,title,fact_text,explanation,source_page,source_section,source_excerpt,importance,confidence,canonical_hash) SELECT b.id,c.id,t.id,d.title,d.body,'Source-derived historic reference with explicit batch verification status.',d.page::integer,d.title,d.body,3,d.confidence::confidence_level,d.canonical_hash FROM d JOIN public.books b ON b.title='Jubayer''s GK' JOIN public.chapters c ON c.book_id=b.id AND c.slug=d.chapter_slug JOIN public.topics t ON t.chapter_id=c.id AND t.slug=d.topic_slug ON CONFLICT (canonical_hash) DO UPDATE SET fact_text=EXCLUDED.fact_text,explanation=EXCLUDED.explanation,confidence=EXCLUDED.confidence;
WITH d(page,chapter_slug,topic_slug,title,body,confidence,canonical_hash) AS (VALUES ('599','europe','marx-engels-and-marxism-source-reference','Marx and Engels — ideological and quotation boundary','Source-visible Marx/Engels works are retained. `father` labels, class-struggle theory summaries, production/culture claims, labor/exploitation assertion, and quotations are not transformed into neutral learner facts.','high','fa5ec0d2995aa4fe2af86480d591a2e94e6ad751b73f9f67807c638d22171a73'),
('600','europe','germany-berlin-wall-past-questions-reference','Berlin Wall past-exam block — historic boundary','Only Q01–Q06 and Q08 meet the complete stem/options/key and historical-consistency threshold. Berlin Wall and reunification wording is stored as historic Cold War material, not current political description.','high','2d25b3c552f367f3526f0d64979f37b02e5de6f9e4da9bdc3bfe25e4dbb9dbf4'),
('601','europe','russia-ussr-and-russian-revolution-reference','Russia and USSR — political and territorial boundary','USSR formation, republic count, dissolution, and successor-state wording are historic source material. No Soviet or Russia-era political label is stated as a timeless contemporary fact.','high','d3d112da173b4e8af770ca15c0ffe0e781ffa56c20f8ef9f25ec106f84d79611'),
('601','europe','russia-ussr-and-russian-revolution-reference','Russia source conflicts — withheld','The scan’s `father of World War II` claim, Stalin/Mussolini Molotov–Ribbentrop signatory line, unclear 1917 republic wording, beard-tax line, and 1710 capital-move claim are withheld rather than corrected into detached facts.','high','9dd3832464c7af6ec0ca02299a1879ec112b830a22ff3456adb7ec29d7ae46bd'),
('602','europe','russia-ussr-and-russian-revolution-reference','Russian Revolution — political-history boundary','The batch retains only bounded chronology, people, historical labels, and location context. Land-seizure quantity, property declaration, military/alignment claims, ten-day duration, and first-socialist-country superlative are withheld.','high','6912956aecfc244cad63ec79c52592c3f7de130ea99ce2743435d70185d4ecd0'),
('603','europe','lenin-stalin-gorbachev-reference','Lenin and Stalin — historical-context boundary','Lenin bibliographic/policy references are retained. RSDLP founding wording, the unreadable 1924 line, incomplete mausoleum claim, *Pravda* control wording, and unqualified Five-Year-Plan statement are withheld. Great Terror is preserved only in evidence-backed historic context.','high','25a33db372161c8761e3a758fd89865b2fe7741c357ceeb13f26cd85e68eb73d'),
('603','europe','lenin-stalin-gorbachev-reference','Gorbachev — reform and collapse boundary','Gorbachev’s final Soviet presidency and reform-era context are retained. The Thatcher quotation is incomplete and withheld; neither Glasnost nor Perestroika is presented as a sole cause of the USSR’s collapse.','high','2e9b5138d093ec5f99177d17dc4dd9f1ace51a12e826a7064b492c4ee4464a66'),
('603','europe','lenin-stalin-gorbachev-reference','Nazi and Soviet terminology safety','The batch does not reproduce political propaganda, ideological slogans, or collective-blame formulations as study facts. All state-system and repression references retain explicit historic scope.','high','3c22b6bee521e8dd8140292657307ae43565033582cd5317c22c591fbfda1ca4')) INSERT INTO public.gk_notes (book_id,chapter_id,topic_id,title,content,source_page,source_section,display_order,confidence,canonical_hash) SELECT b.id,c.id,t.id,d.title,d.body,d.page::integer,d.title,d.page::integer,d.confidence::confidence_level,d.canonical_hash FROM d JOIN public.books b ON b.title='Jubayer''s GK' JOIN public.chapters c ON c.book_id=b.id AND c.slug=d.chapter_slug JOIN public.topics t ON t.chapter_id=c.id AND t.slug=d.topic_slug ON CONFLICT (canonical_hash) DO UPDATE SET content=EXCLUDED.content,confidence=EXCLUDED.confidence;
COMMIT;